CREATE TABLE site_settings(key TEXT PRIMARY KEY,value_json JSONB NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_by BIGINT REFERENCES users(id),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE page_banners(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,asset_id BIGINT NOT NULL REFERENCES media_assets(id),target_path TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),starts_at TIMESTAMPTZ,ends_at TIMESTAMPTZ,version INTEGER NOT NULL DEFAULT 1,CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at));
INSERT INTO permissions(code) VALUES('promotions.manage') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='admin' ON CONFLICT DO NOTHING;
